class WordRainEngine {
  constructor(pool, difficulty = 'easy', random = Math.random) {
    this.difficulty = ['easy', 'normal', 'fast'].includes(difficulty) ? difficulty : 'easy';
    const settings = { easy: [14, 4.5], normal: [10, 3.3], fast: [7, 2.4] }[this.difficulty];
    [this._lifetime, this._interval] = settings;
    this._random = typeof random === 'function' ? random : Math.random;
    const seen = new Set();
    this._pool = (Array.isArray(pool) ? pool : []).filter(word => {
      if (!word || word.id == null || typeof word.en !== 'string' || !word.en.trim() || seen.has(word.id)) return false;
      seen.add(word.id);
      return true;
    });
    this.duration = this.remaining = 60;
    this.lives = 5;
    this.score = this.combo = this.bestCombo = this.caught = 0;
    this.missed = [];
    this.active = [];
    this.maxActive = 3;
    this.done = false;
    this.reason = null;
    this._bag = [];
    this._nextSpawn = this._interval;
    this._serial = 0;
    if (this._pool.length) this._spawn();
    else this.finish('empty');
  }

  _index(length) {
    const value = this._random();
    return Math.floor(Math.max(0, Math.min(0.999999999, Number.isFinite(value) ? value : 0)) * length);
  }

  _spawn() {
    const limit = Number.isFinite(this.maxActive) ? Math.max(1, Math.min(3, Math.floor(this.maxActive))) : 3;
    if (this.active.length >= limit) return null;
    const ids = new Set(this.active.map(item => item.word.id));
    const eligible = this._pool.filter(word => !ids.has(word.id));
    if (!eligible.length) return null;
    let candidates = this._bag.filter(word => !ids.has(word.id));
    if (!candidates.length) {
      this._bag = this._pool.slice();
      candidates = eligible;
    }
    const word = candidates[this._index(candidates.length)];
    this._bag.splice(this._bag.indexOf(word), 1);
    const occupied = new Set(this.active.map(item => item.lane));
    const lanes = [0, 1, 2].filter(lane => !occupied.has(lane));
    const item = { token: ++this._serial, word, progress: 0, lane: lanes[this._index(lanes.length)] };
    this.active.push(item);
    return item;
  }

  advance(seconds) {
    const events = [];
    if (this.done || !Number.isFinite(seconds) || seconds <= 0) return events;
    const epsilon = 1e-9;
    while (seconds > 0 && !this.done) {
      const nextMiss = this.active.length ? Math.min(...this.active.map(item => (1 - item.progress) * this._lifetime)) : Infinity;
      const step = Math.max(0, Math.min(seconds, this.remaining, this._nextSpawn, nextMiss));
      this.active.forEach(item => { item.progress = Math.min(1, item.progress + step / this._lifetime); });
      this.remaining = Math.max(0, this.remaining - step);
      this._nextSpawn -= step;
      seconds -= step;
      if (this.remaining <= epsilon) {
        this.remaining = 0;
        this.finish('time');
        events.push({ type: 'finish', reason: this.reason });
        break;
      }
      for (const item of this.active.slice()) {
        if (item.progress < 1 - epsilon) continue;
        this.active.splice(this.active.indexOf(item), 1);
        this.missed.push(item.word);
        this.lives--;
        this.combo = 0;
        events.push({ type: 'miss', item, word: item.word });
        if (!this.lives) {
          this.finish('lives');
          events.push({ type: 'finish', reason: this.reason });
          break;
        }
      }
      if (!this.done && this._nextSpawn <= epsilon) {
        this._nextSpawn = this._interval;
        const item = this._spawn();
        if (item) events.push({ type: 'spawn', item });
      }
    }
    return events;
  }

  submit(text) {
    if (this.done || typeof text !== 'string') return { correct: false };
    const answer = text.trim().toLowerCase();
    const index = this.active.findIndex(item => item.word.en.trim().toLowerCase() === answer);
    if (index < 0) return { correct: false };
    const { word } = this.active.splice(index, 1)[0];
    this.caught++;
    this.combo++;
    this.bestCombo = Math.max(this.bestCombo, this.combo);
    const points = 100 + Math.min(this.combo - 1, 5) * 20;
    this.score += points;
    return { correct: true, word, points };
  }

  finish(reason = 'stopped') {
    if (this.done) return;
    this.done = true;
    this.reason = reason;
  }
}
globalThis.WordRainEngine = WordRainEngine;

// Word rain: DOM and animation controller. The model never advances while paused.
let rainGame=null,rainDifficulty='easy',rainPaused=false,rainFrame=0,rainLastTime=null,rainResumeAfterDialog=false,rainSaved=false;
let rainElements=new Map(),rainLesson='',rainFeedbackTimer=0,rainComposing=false;
const RAIN_LEVELS={easy:{name:'천천히',icon:'🌱',detail:'처음 시작하는 친구에게'},normal:{name:'보통',icon:'🌿',detail:'익숙해졌다면 도전!'},fast:{name:'빠르게',icon:'⚡',detail:'손가락이 준비됐다면'}};
function rainBest(){return saved.gameBest?.[rainDifficulty]||0;}
function renderGame(){
 document.body.classList.toggle('rain-playing',!!rainGame&&!rainGame.done);
 if(rainGame){if(rainGame.done)renderGameResults();else renderGamePlay();return;}
 $('workspace').innerHTML=`<div class="view-top"><div><h2>그림과 함께, 단어 톡톡!</h2><p>내려오는 그림과 영어 단어를 보고 빠르게 입력해요.</p></div><span class="game-label">WORD RAIN</span></div>${renderFilters()}<div class="rain-preview" aria-hidden="true"><span class="preview-spark spark-one">✦</span><span class="preview-spark spark-two">✧</span><div class="rain-preview-word"><span class="rain-picture">${esc(currentWords()[0]?.emoji||'📘')}</span><strong lang="en">${esc(currentWords()[0]?.en||'word')}</strong></div><div class="preview-ground">그림을 보고 · 영어를 쓰고 · 점수를 쌓아요</div></div><div class="rain-rules"><span>⏱️ 한 판 60초</span><span>💚 기회 5번</span><span>⌨️ 입력 후 Enter</span></div><div class="setting-block"><div class="label">떨어지는 속도를 골라 주세요</div><div class="rain-speeds">${Object.entries(RAIN_LEVELS).map(([id,d])=>`<button class="rain-speed ${rainDifficulty===id?'selected':''}" data-action="rain-speed" data-speed="${id}" aria-pressed="${rainDifficulty===id}"><span aria-hidden="true">${d.icon}</span><strong>${d.name}</strong><small>${d.detail}</small></button>`).join('')}</div></div><p class="rain-help">같은 영어 단어를 입력하면 그림과 단어가 함께 사라져요.<br>바닥에 닿으면 하트가 하나 줄어요. 오타는 고쳐서 다시 입력하면 돼요.</p><div class="rain-start-row"><span>🏆 ${RAIN_LEVELS[rainDifficulty].name} 최고 <strong>${rainBest()}</strong>점</span><button class="btn btn-primary" data-action="rain-start">게임 시작하기 ${icon('game')}</button></div>`;
}
function startRainGame(){
 stopRainLoop();stopSpeech();rainGame=new WordRainEngine(currentWords(),rainDifficulty);rainLesson=lessonLabel();rainPaused=false;rainSaved=false;rainLastTime=null;rainComposing=false;view='game';render();
 if(rainGame.done)return;
 $('workspace').scrollIntoView({block:'start',behavior:'instant'});$('rainInput').focus({preventScroll:true});fitRainStage();scheduleRainFrame();
}
function renderGamePlay(){
 $('workspace').innerHTML=`<div class="rain-play-header"><div><h2>단어 톡톡!</h2><p>${esc(rainLesson)} · ${RAIN_LEVELS[rainDifficulty].name}</p></div><div class="rain-controls"><button class="btn btn-soft" id="rainPauseButton" data-action="rain-pause">잠깐 쉬기</button><button class="icon-btn" data-action="rain-exit" aria-label="게임 나가기">✕</button></div></div><div class="rain-hud"><div><small>내 점수</small><strong id="rainScore">0</strong></div><div><small>남은 시간</small><strong id="rainTime">60<em>초</em></strong></div><div><small>남은 기회</small><strong class="rain-lives" id="rainLives" aria-label="남은 기회 5번">♥♥♥♥♥</strong></div></div><div class="rain-stage" id="rainStage" role="region" aria-label="그림 단어가 내려오는 게임 화면"><div class="rain-sky-label" aria-hidden="true">CATCH A WORD, GROW YOUR WORLD</div><div class="rain-floor" aria-hidden="true">여기에 닿기 전에 잡아 주세요!</div><div class="rain-tokens" id="rainTokens"></div><div class="rain-pause-cover" id="rainPauseCover" hidden><span aria-hidden="true">🌿</span><h3>잠깐 쉬어 가요</h3><p>단어와 시간도 함께 멈췄어요.</p><button class="btn btn-primary" data-action="rain-resume">계속하기</button></div></div><div class="rain-feedback" id="rainFeedback" role="status" aria-live="polite">내려오는 영어 단어를 그대로 입력해 주세요.</div><form class="rain-input-row" id="rainForm"><label class="sr-only" for="rainInput">내려오는 영어 단어 입력</label><input id="rainInput" lang="en" type="text" inputmode="url" autocomplete="off" autocapitalize="none" spellcheck="false" enterkeyhint="go" maxlength="120" placeholder="영어 단어 입력" aria-describedby="rainFeedback"><button class="btn btn-lime" id="rainSubmit" type="submit">맞히기</button></form><p class="rain-input-hint">Enter로 맞히기 · 대소문자 구분 없음 · 연속 정답은 보너스!</p>`;
 rainElements=new Map();fitRainStage();paintRainWords();updateRainHud();if(rainPaused)showRainPaused();
}
function fitRainStage(){
 if(!rainGame||rainGame.done||view!=='game'||!$('rainStage'))return;
 const height=window.visualViewport?.height||window.innerHeight;
 const compact=height<640||window.innerWidth<=760;
 let stageHeight=Math.max(170,Math.min(430,height-270));
 // Keep existing cards spaced while a resized screen drains down to one card.
 if(stageHeight<300&&rainGame.active.length>1)stageHeight=300;
 document.documentElement.style.setProperty('--rain-stage-height',`${stageHeight}px`);
 rainGame.maxActive=compact?1:3;
}
function scheduleRainFrame(){if(!rainFrame&&!rainPaused&&rainGame&&!rainGame.done&&view==='game')rainFrame=requestAnimationFrame(rainTick);}
function stopRainLoop(){if(rainFrame)cancelAnimationFrame(rainFrame);rainFrame=0;rainLastTime=null;}
function rainTick(now){
 rainFrame=0;if(!rainGame||rainGame.done||rainPaused||view!=='game')return;
 const delta=rainLastTime===null?0:(now-rainLastTime)/1000;rainLastTime=now;
 // A stalled/background page resumes paused instead of losing unseen words.
 if(delta>1.5){pauseRainGame();return;}
 const events=rainGame.advance(delta);
 for(const event of events){if(event.type==='miss')setRainFeedback(`다음에 다시 만나요: ${event.word.en} · ${event.word.ko}`,false);}
 if(rainGame.done){finishRainGameUI();return;}
 if(events.length)fitRainStage();paintRainWords();updateRainHud();scheduleRainFrame();
}
function paintRainWords(){
 const field=$('rainStage'),layer=$('rainTokens');if(!field||!layer||!rainGame)return;
 const current=new Set(rainGame.active.map(w=>w.token));
 for(const [id,node]of rainElements){if(!current.has(id)){node.remove();rainElements.delete(id);}}
 for(const item of rainGame.active){let node=rainElements.get(item.token);if(!node){node=document.createElement('div');node.className='rain-word';node.innerHTML=`<span class="rain-picture" role="img" aria-label="${esc(item.word.ko)} 그림">${esc(item.word.emoji)}</span><strong lang="en">${esc(item.word.en)}</strong>`;layer.appendChild(node);rainElements.set(item.token,node);}
 const width=node.offsetWidth,height=node.offsetHeight,padding=10;
 const lanePosition=[.18,.5,.82][item.lane%3];const x=Math.max(padding,Math.min(field.clientWidth-width-padding,field.clientWidth*lanePosition-width/2));
 const y=8+item.progress*Math.max(0,field.clientHeight-height-35);
 node.style.transform=`translate3d(${Math.round(x)}px,${Math.round(y)}px,0)`;node.classList.toggle('near-floor',item.progress>.78);
 }
}
function updateRainHud(){if(!rainGame||!$('rainScore'))return;$('rainScore').textContent=rainGame.score;$('rainTime').innerHTML=`${Math.ceil(rainGame.remaining)}<em>초</em>`;$('rainTime').classList.toggle('last-seconds',rainGame.remaining<=10);$('rainLives').textContent='♥'.repeat(rainGame.lives)+'♡'.repeat(5-rainGame.lives);$('rainLives').setAttribute('aria-label',`남은 기회 ${rainGame.lives}번`);}
function setRainFeedback(message,correct){const el=$('rainFeedback');if(!el)return;clearTimeout(rainFeedbackTimer);el.textContent=message;el.classList.toggle('is-correct',correct);el.classList.toggle('is-miss',!correct);}
function submitRainWord(){
 if(!rainGame||rainGame.done||rainPaused||rainComposing)return;const input=$('rainInput'),value=input.value;if(!value.trim()){input.focus();return;}
 const result=rainGame.submit(value);
 if(result.correct){input.value='';setRainFeedback(`${result.word.en} · ${result.word.ko}  +${result.points}점${rainGame.combo>1?'  ✦ '+rainGame.combo+'연속!':''}`,true);fitRainStage();paintRainWords();updateRainHud();
 // Copying a visible word counts as practice, not proof of vocabulary mastery.
 const d=today();saved.days[d]||=[];if(!saved.days[d].includes(result.word.id)){saved.days[d].push(result.word.id);save();}
 }else{setRainFeedback('아직 맞는 단어가 없어요. 철자를 확인하고 다시 입력해요.',false);input.select();}
 input.focus({preventScroll:true});
}
function showRainPaused(){if(!$('rainPauseCover'))return;$('rainPauseCover').hidden=false;$('rainInput').disabled=true;$('rainSubmit').disabled=true;$('rainPauseButton').textContent='계속하기';}
function pauseRainGame(){if(!rainGame||rainGame.done||rainPaused)return;rainPaused=true;stopRainLoop();showRainPaused();}
function resumeRainGame(){if(!rainGame||rainGame.done||document.hidden)return;rainPaused=false;rainLastTime=null;$('rainPauseCover').hidden=true;$('rainInput').disabled=false;$('rainSubmit').disabled=false;$('rainPauseButton').textContent='잠깐 쉬기';$('rainInput').focus({preventScroll:true});scheduleRainFrame();}
function finishRainGameUI(){stopRainLoop();rainPaused=false;document.body.classList.remove('rain-playing');if(!rainSaved){saved.gameBest||={};saved.gameBest[rainDifficulty]=Math.max(rainBest(),rainGame.score);save();rainSaved=true;}renderGameResults();}
function renderGameResults(){
 document.body.classList.remove('rain-playing');const missed=[...new Map(rainGame.missed.map(w=>[w.id,w])).values()];
 $('workspace').innerHTML=`<div class="result entry"><div class="result-emoji" aria-hidden="true">${rainGame.caught>=10?'🏆':'🌳'}</div><h2>${rainGame.reason==='time'?'60초 도전 완료!':'단어를 잡으며 한 뼘 자랐어요!'}</h2><p>${esc(rainLesson)} · ${RAIN_LEVELS[rainDifficulty].name}</p><div class="score">${rainGame.score}<small> 점</small></div><div class="rain-result-stats"><span>잡은 단어 <strong>${rainGame.caught}개</strong></span><span>최고 연속 <strong>${rainGame.bestCombo}개</strong></span><span>최고 기록 <strong>${rainBest()}점</strong></span></div><div class="result-actions"><button class="btn btn-lime" data-action="rain-start">한 번 더 하기</button><button class="btn btn-outline" data-action="rain-settings">속도·단어 바꾸기</button><button class="btn btn-primary" data-action="nav" data-view="practice">단어 연습하기</button></div>${missed.length?`<div class="result-list"><h3>다시 만나 볼 단어</h3><p class="small muted" style="margin-top:7px">놓친 단어는 여기서 한 번 더 살펴봐요.</p>${missed.map(w=>`<div class="result-item"><div><span class="rain-result-picture" aria-hidden="true">${esc(w.emoji)}</span><strong lang="en">${esc(w.en)}</strong> ${esc(w.ko)}</div><button class="icon-btn" data-action="speak" data-id="${w.id}" aria-label="${esc(w.en)} 발음 듣기">${icon('sound')}</button></div>`).join('')}</div>`:''}</div>`;
 $('workspace').scrollIntoView({block:'start',behavior:'instant'});
}
